#!/bin/sh
python3 -S -c 'exec("import sys,functools as f;sys.set_int_max_str_digits(0)\ns=open(sys.argv[1]).read();L=[];B={}\nfor l in s.splitlines():\n l=l.split(\"#\",1)[0].strip()\n if not l:continue\n if l[-1]==\":\":B[l[:-1]]=len(L)\n else:L+=[l.split()]\nC=[i for i,t in enumerate(L)if t[0].upper()==\"CALL\"];F=[\"r\"+str(i+1)for i in C];X=\"0123456789_\";R=[];A=lambda q,x,n,w,d:R.append((q,x,n,w,d));Q=lambda i,a:f\"q{i}a{a}\";M=lambda x:\"m\"+x;A(\"B\",\"|\",Q(0,0),\"|\",\"R\")\nfor i,t in enumerate(L):\n o=t[0].upper();n=i+1\n for a in range(10):\n  q=Q(i,a)\n  if o==\"HALT\":continue\n  if o==\"LOAD\":\n   for x in X:A(q,x,Q(n,int(x)if x<\":\"else 0),x,\"S\")\n  elif o==\"STORE\":\n   for x in X:A(q,x,Q(n,a),str(a),\"S\")\n  elif o==\"ADD\":\n   for x in X:A(q,x,Q(n,(a+int(t[1]))%10),x,\"S\")\n  elif o==\"CMP\":\n   d=B[t[2]]if str(a)==t[1]else n\n   for x in X:A(q,x,Q(d,a),x,\"S\")\n  elif o==\"CALL\":\n   d=B[t[1]];z=f\"C{i}a{a}\"\n   for x in X:A(q,x,z,M(x),\"L\")\n   for x in X:A(z,x,z,x,\"L\")\n   A(z,\"|\",z+\"f\",\"|\",\"L\")\n   for y in F:A(z+\"f\",y,z+\"f\",y,\"L\")\n   A(z+\"f\",\"_\",z+\"b\",\"r\"+str(n),\"R\")\n   for y in F:A(z+\"b\",y,z+\"b\",y,\"R\")\n   A(z+\"b\",\"|\",z+\"r\",\"|\",\"R\")\n   for x in X:A(z+\"r\",x,z+\"r\",x,\"R\")\n   for x in X:A(z+\"r\",M(x),Q(d,a),x,\"S\")\n  elif o==\"RETURN\":\n   z=f\"T{i}a{a}\"\n   for x in X:A(q,x,z,M(x),\"L\")\n   for x in X:A(z,x,z,x,\"L\")\n   A(z,\"|\",z+\"f\",\"|\",\"L\")\n   for y in F:A(z+\"f\",y,z+\"f\",y,\"L\")\n   A(z+\"f\",\"_\",z+\"p\",\"_\",\"R\")\n   for c in C:\n    v=c+1;y=z+\"b\"+str(v);A(z+\"p\",\"r\"+str(v),y,\"_\",\"R\")\n    for e in F:A(y,e,y,e,\"R\")\n    A(y,\"|\",y+\"r\",\"|\",\"R\")\n    for x in X:A(y+\"r\",x,y+\"r\",x,\"R\")\n    for x in X:A(y+\"r\",M(x),Q(v,a),x,\"S\")\n  else:raise SystemExit(\"bad:\"+o)\np=\";\".join(\",\".join(x)for x in R);E=lambda x:f.reduce(lambda a,b:a*257+b+1,x.encode(),1);print(\"PROGRAM=\"+repr(p));print(\"GPROGRAM=\"+str(E(p)));print(\"START=B\");print(\"RULES=\"+str(len(R)))")' "$1"
